$r,'SENDER'),$get($r,'TELL'),$get($r,'RECEIVE'),$get($r,'DESCRIPTION'),$get($r,'PAYMENT RECEIVE')?:'Unpaid',$airline,$get($r,'FLY AWB NO'),'Pending',$me['id'],$me['branch_id'],$me['branch_id']]);$shipmentId=(int)$pdo->lastInsertId();$invNo=create_shipment_invoice($shipmentId,round((float)$get($r,'KG')*(float)$get($r,'RATE'),2),(string)$me['id']);$pdo->commit();$ok++;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();}}$result[]="$ok shipments imported.";}}}
